import { useLayoutEffect, useMemo, useState } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { Button, Notice } from '@wordpress/components';
import { DataForm } from '@wordpress/dataviews/wp';
import type { Field, Form } from '@wordpress/dataviews/wp';
import { useMutation } from '@tanstack/react-query';
import { saveToneFeelMutation } from '@/queries/tone-feel';
import type { ToneFeelResult } from '@/queries/tone-feel';
import './style.scss';

interface ToneFeelFormData {
	summary: string;
	traitsRaw: string;
	fields: string;
}

const computeFormData = (
	initialData?: ToneFeelResult
): ToneFeelFormData | null => {
	if ( initialData ) {
		return {
			summary: initialData.summary ?? '',
			traitsRaw: ( initialData.traits ?? [] ).join( ', ' ),
			fields: initialData.fields ?? '',
		};
	}

	return null;
};

export default function ToneReview( {
	initialData,
	onSaved,
}: {
	initialData?: ToneFeelResult;
	onSaved?: () => void;
} ) {
	const [ formData, setFormData ] = useState< ToneFeelFormData | null >( () =>
		computeFormData( initialData )
	);
	const {
		mutate: saveToneFeel,
		isPending: isSaving,
		error,
	} = useMutation( saveToneFeelMutation() );

	useLayoutEffect( () => {
		setFormData( computeFormData( initialData ) );
	}, [ initialData ] );

	const fields = useMemo< Array< Field< ToneFeelFormData > > >(
		() => [
			{
				id: 'summary',
				type: 'text',
				label: __( 'Summary', 'wcai-pa' ),
				Edit: {
					control: 'textarea' as const,
					rows: 4,
				},
			},
			{
				id: 'traitsRaw',
				type: 'text',
				label: __( 'Traits (comma-separated)', 'wcai-pa' ),
			},
			{
				id: 'fields',
				type: 'text',
				label: __( 'Field guidelines', 'wcai-pa' ),
				Edit: {
					control: 'textarea' as const,
					rows: 10,
				},
			},
		],
		[]
	);

	const form = useMemo< Form >(
		() => ( {
			layout: {
				type: 'regular' as const,
				labelPosition: 'top' as const,
			},
			fields: [ 'summary', 'traitsRaw', 'fields' ],
		} ),
		[]
	);

	if ( ! formData ) {
		return null;
	}

	const handleSave = () => {
		const traits = formData.traitsRaw
			.split( ',' )
			.map( ( t ) => t.trim() )
			.filter( Boolean );
		saveToneFeel(
			{
				summary: formData.summary,
				traits,
				fields: formData.fields,
			},
			{ onSuccess: () => onSaved?.() }
		);
	};

	return (
		<div className="wcai-pa-tone-review">
			{ error && (
				<Notice
					status="error"
					isDismissible={ false }
					className="wcai-pa-mutation-error-notice"
				>
					{ error.message }
				</Notice>
			) }
			<DataForm
				data={ formData }
				fields={ fields }
				form={ form }
				onChange={ ( edits ) =>
					setFormData( ( current ) =>
						current ? { ...current, ...edits } : current
					)
				}
			/>
			<Button
				variant="primary"
				onClick={ handleSave }
				disabled={ isSaving }
				__next40pxDefaultSize
				className="wcai-pa-tone-review__save-button"
			>
				{ __( 'Save', 'wcai-pa' ) }
			</Button>
		</div>
	);
}
