import { useEffect, useId, useRef } from 'react';

declare global {
	interface Window {
		wp?: {
			oldEditor?: {
				initialize: (
					id: string,
					settings: {
						tinymce?: boolean | Record< string, unknown >;
						quicktags?: boolean | Record< string, unknown >;
						mediaButtons?: boolean;
					}
				) => void;
				remove: ( id: string ) => void;
			};
		};
		tinymce?: {
			get: ( id: string ) => {
				on: ( event: string, callback: () => void ) => void;
				getContent: () => string;
				setContent: ( content: string ) => void;
			} | null;
		};
	}
}

interface RichTextEditorProps {
	value: string;
	onChange: ( value: string ) => void;
}

export default function RichTextEditor( {
	value,
	onChange,
}: RichTextEditorProps ) {
	const reactId = useId();
	// TinyMCE / wp.editor expects a DOM-safe id; replace any colons React inserts.
	const editorId = `wcai-pa-rich-${ reactId.replace(
		/[^a-zA-Z0-9_-]/g,
		'-'
	) }`;

	const onChangeRef = useRef( onChange );
	onChangeRef.current = onChange;

	useEffect( () => {
		const oldEditor = window.wp?.oldEditor;
		if ( ! oldEditor ) {
			return;
		}

		oldEditor.initialize( editorId, {
			tinymce: {
				wpautop: true,
				plugins:
					'charmap colorpicker compat3x directionality fullscreen hr image lists media paste tabfocus textcolor wordpress wpautoresize wpdialogs wpeditimage wpemoji wpgallery wplink wptextpattern wpview',
				toolbar1:
					'formatselect bold italic bullist numlist blockquote alignleft aligncenter alignright link unlink wp_more',
				toolbar2: '',
			},
			quicktags: true,
			mediaButtons: false,
		} );

		const tinymce = window.tinymce;
		const editor = tinymce?.get( editorId );

		const handleChange = () => {
			const current = tinymce?.get( editorId );
			if ( current ) {
				onChangeRef.current( current.getContent() );
			}
		};

		if ( editor ) {
			editor.on( 'change', handleChange );
			editor.on( 'keyup', handleChange );
			editor.on( 'undo', handleChange );
			editor.on( 'redo', handleChange );
		}

		return () => {
			oldEditor.remove( editorId );
		};
	}, [ editorId ] );

	return (
		<div className="wcai-pa-rich-text-editor">
			<textarea
				id={ editorId }
				defaultValue={ value }
				onChange={ ( event ) =>
					onChangeRef.current( event.target.value )
				}
				rows={ 10 }
				style={ { width: '100%' } }
			/>
		</div>
	);
}
