import {
	Button,
	Card,
	CardBody,
	Notice,
	__experimentalHStack as HStack,
	__experimentalVStack as VStack,
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { useMutation } from '@tanstack/react-query';
import { disconnectUserMutation } from '@/queries/connection';

import './style.scss';

export default function ConnectionCard(): JSX.Element {
	const {
		mutate: disconnect,
		isPending,
		error,
	} = useMutation( disconnectUserMutation() );

	return (
		<Card size="medium" className="wcai-pa-connection-card">
			<CardBody>
				<VStack>
					<HStack>
						<span className="wcai-pa-connection-card__status">
							<span
								className="wcai-pa-connection-card__dot"
								aria-hidden="true"
							/>
							{ __( 'Connected to WordPress.com', 'wcai-pa' ) }
						</span>
						<Button
							variant="secondary"
							isSmall
							onClick={ () =>
								disconnect( undefined, {
									onSuccess: () => {
										window.location.reload();
									},
								} )
							}
							isBusy={ isPending }
							disabled={ isPending }
						>
							{ __( 'Disconnect', 'wcai-pa' ) }
						</Button>
					</HStack>
					{ error && (
						<Notice status="error" isDismissible={ false }>
							{ error.message }
						</Notice>
					) }
				</VStack>
			</CardBody>
		</Card>
	);
}
