import {
	mutationOptions,
	queryOptions,
	type QueryKey,
} from '@tanstack/react-query';
import { apiFetch } from './api-fetch';
import { queryClient } from '@/lib/query-client';

interface Analysis {
	summary: string;
	traits: string[];
	fields: Record< string, string >;
}

export interface ToneFeelAnalysisResult {
	current: Analysis;
	recommended: Analysis;
}

interface ToneFeelAnalysisStatus {
	status: 'not_started' | 'queued' | 'running' | 'stored' | 'failed';
	result?: ToneFeelAnalysisResult;
}

async function fetchToneFeelAnalysis(): Promise< ToneFeelAnalysisStatus > {
	return apiFetch< ToneFeelAnalysisStatus >( {
		path: '/wcai-pa/v1/tone-feel/analysis',
	} );
}

async function triggerToneFeelAnalysis(): Promise< ToneFeelAnalysisStatus > {
	return apiFetch< ToneFeelAnalysisStatus >( {
		path: '/wcai-pa/v1/tone-feel/analysis',
		method: 'POST',
	} );
}

const toneFeelAnalysisQueryKey: QueryKey = [ 'tone-feel-analysis' ];

export const toneFeelAnalysisQuery = () =>
	queryOptions( {
		queryKey: toneFeelAnalysisQueryKey,
		queryFn: fetchToneFeelAnalysis,
	} );

export const triggerToneFeelAnalysisMutation = () =>
	mutationOptions( {
		mutationFn: triggerToneFeelAnalysis,
		onSuccess: () => {
			queryClient.invalidateQueries( {
				queryKey: toneFeelAnalysisQueryKey,
			} );
		},
	} );
