import {
	createHashHistory,
	createRootRoute,
	createRoute,
	createRouter,
	redirect,
} from '@tanstack/react-router';
import Overview from './screens/overview';
import Settings from './screens/settings';
import Suggestions from './screens/suggestions';
import History from './screens/history';
import Onboarding from './screens/onboarding';
import RootRoute from './components/root-route';
import { syncSidebarHighlight } from './lib/sync-sidebar-highlight';
import { syncPageTitle } from './lib/sync-page-title';
import { config } from './lib/config';

const hashHistory = createHashHistory();

const rootRoute = createRootRoute( {
	component: RootRoute,
} );

const onboardingGuard = () => {
	if (
		! config.tosAccepted ||
		! config.onboardingComplete ||
		! config.isUserConnected ||
		! config.isRegistered
	) {
		throw redirect( { to: '/onboarding' } );
	}
};

const overviewRoute = createRoute( {
	getParentRoute: () => rootRoute,
	path: '/',
	beforeLoad: onboardingGuard,
	component: Overview,
} );

const settingsRoute = createRoute( {
	getParentRoute: () => rootRoute,
	path: '/settings',
	beforeLoad: onboardingGuard,
	component: Settings,
} );

const suggestionsRoute = createRoute( {
	getParentRoute: () => rootRoute,
	path: '/suggestions',
	beforeLoad: onboardingGuard,
	component: Suggestions,
} );

const historyRoute = createRoute( {
	getParentRoute: () => rootRoute,
	path: '/history',
	beforeLoad: onboardingGuard,
	component: History,
} );

const onboardingRoute = createRoute( {
	getParentRoute: () => rootRoute,
	beforeLoad: () => {
		if (
			config.tosAccepted &&
			config.onboardingComplete &&
			config.isUserConnected &&
			config.isRegistered
		) {
			throw redirect( { to: '/' } );
		}
	},
	path: '/onboarding',
	component: Onboarding,
} );

const routeTree = rootRoute.addChildren( [
	overviewRoute,
	settingsRoute,
	suggestionsRoute,
	historyRoute,
	onboardingRoute,
] );

export const router = createRouter( {
	routeTree,
	history: hashHistory,
} );

hashHistory.subscribe( ( { location } ) => {
	syncSidebarHighlight( location.pathname );
	syncPageTitle( location.pathname );
} );
syncSidebarHighlight( hashHistory.location.pathname );
syncPageTitle( hashHistory.location.pathname );

declare module '@tanstack/react-router' {
	interface Register {
		router: typeof router;
	}
}
