import {
	Button,
	Modal,
	TextareaControl,
	TextControl,
	__experimentalNumberControl as NumberControl,
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { useState } from 'react';
import RichTextEditor from '../rich-text-editor';
import type { ProductSuggestionFieldType } from '@/queries/suggestion';

interface EditFieldModalProps {
	productName: string;
	fieldLabel: string;
	fieldType: ProductSuggestionFieldType;
	newValue: string;
	onClose: () => void;
	onSave: ( value: string ) => void;
}

export default function EditFieldModal( {
	productName,
	fieldLabel,
	fieldType,
	newValue,
	onClose,
	onSave,
}: EditFieldModalProps ) {
	const [ localValue, setLocalValue ] = useState( newValue );

	const renderControl = () => {
		switch ( fieldType ) {
			case 'rich':
				return (
					<RichTextEditor
						value={ localValue }
						onChange={ setLocalValue }
					/>
				);
			case 'number':
				return (
					<NumberControl
						__next40pxDefaultSize
						value={ localValue }
						onChange={ ( value ) => setLocalValue( value ?? '' ) }
					/>
				);
			case 'text':
				// Short single-line text is more common; if the value contains
				// newlines fall back to a textarea so the user keeps formatting.
				if ( localValue.includes( '\n' ) ) {
					return (
						<TextareaControl
							value={ localValue }
							onChange={ setLocalValue }
						/>
					);
				}
				return (
					<TextControl
						__next40pxDefaultSize
						value={ localValue }
						onChange={ setLocalValue }
					/>
				);
			default:
				return (
					<TextareaControl
						value={ localValue }
						onChange={ setLocalValue }
					/>
				);
		}
	};

	return (
		<Modal
			size={ fieldType === 'rich' ? 'large' : 'medium' }
			onRequestClose={ onClose }
			title={ __( 'Edit field', 'wcai-pa' ) }
		>
			<ul style={ { marginTop: 0 } }>
				<li>
					<strong>{ __( 'Product:', 'wcai-pa' ) }</strong>{ ' ' }
					{ productName }
				</li>
				<li>
					<strong>{ __( 'Field:', 'wcai-pa' ) }</strong>{ ' ' }
					{ fieldLabel }
				</li>
			</ul>
			{ renderControl() }
			<div
				style={ {
					display: 'flex',
					justifyContent: 'flex-end',
					marginTop: '24px',
				} }
			>
				<Button
					__next40pxDefaultSize
					variant="primary"
					onClick={ () => onSave( localValue ) }
				>
					{ __( 'Save', 'wcai-pa' ) }
				</Button>
			</div>
		</Modal>
	);
}
