import { __, _n, sprintf } from '@wordpress/i18n';
import type { OverviewSummary as OverviewSummaryData } from '@/queries/overview';

import './style.scss';

interface Props {
	summary: OverviewSummaryData;
}

export default function OverviewSummary( {
	summary,
}: Props ): JSX.Element | null {
	if ( summary.total_changed === 0 ) {
		return null;
	}

	const productsLabel = sprintf(
		/* translators: %d: number of products with applied changes */
		_n(
			'%d changed product',
			'%d changed products',
			summary.total_changed,
			'wcai-pa'
		),
		summary.total_changed
	);

	const breakdown = sprintf(
		/* translators: 1: lifted count, 2: no-change count, 3: dipped count, 4: too-early count */
		__(
			'(%1$d lifted, %2$d no change, %3$d dipped, %4$d too early)',
			'wcai-pa'
		),
		summary.lifted_count,
		summary.no_change_count,
		summary.dipped_count,
		summary.not_enough_data_count
	);

	const headline = buildHeadline( summary, productsLabel );

	return (
		<p className="wcai-pa-overview-summary">
			<span className="wcai-pa-overview-summary__headline">
				{ headline }
			</span>{ ' ' }
			<span className="wcai-pa-overview-summary__breakdown">
				{ breakdown }
			</span>
		</p>
	);
}

function buildHeadline(
	summary: OverviewSummaryData,
	productsLabel: string
): string {
	const lift = summary.average_lift_percent;
	const allPending = summary.not_enough_data_count === summary.total_changed;

	if ( allPending || lift === null ) {
		return sprintf(
			/* translators: %s: a phrase like "12 changed products" */
			__( 'Outcome data still pending across %s.', 'wcai-pa' ),
			productsLabel
		);
	}

	const rounded = Math.round( Math.abs( lift ) );

	if ( lift > 0 ) {
		return sprintf(
			/* translators: 1: percent like 7, 2: phrase like "12 changed products" */
			__(
				'AI suggestions are lifting orders ~%1$d%% on average across %2$s.',
				'wcai-pa'
			),
			rounded,
			productsLabel
		);
	}
	if ( lift < 0 ) {
		return sprintf(
			/* translators: 1: percent like 7, 2: phrase like "12 changed products" */
			__(
				'AI suggestions are reducing orders ~%1$d%% on average across %2$s.',
				'wcai-pa'
			),
			rounded,
			productsLabel
		);
	}
	return sprintf(
		/* translators: %s: a phrase like "12 changed products" */
		__( 'AI suggestions show no average effect across %s.', 'wcai-pa' ),
		productsLabel
	);
}
