import {
	infiniteQueryOptions,
	mutationOptions,
	queryOptions,
	type QueryKey,
} from '@tanstack/react-query';
import { apiFetch } from './api-fetch';
import { queryClient } from '@/lib/query-client';

export interface OverviewStats {
	pending: number | null;
	applied_7d: number | null;
	approval_rate_30d: number | null;
	total_suggestions: number | null;
	weekly_suggestions_used: number | null;
	weekly_suggestions_limit: number | null;
}

export type OverviewVerdict =
	| 'lifted'
	| 'no_change'
	| 'dipped'
	| 'not_enough_data';

export interface OverviewAppliedProduct {
	product_id: number;
	product_name: string;
	last_applied_at: string | null;
	verdict: OverviewVerdict;
	magnitude_percent: number | null;
	actual_orders: number;
	expected_orders: number | null;
	days_since_change: number;
	days_of_baseline: number;
	edit_url?: string;
}

export interface OverviewSummary {
	total_changed: number;
	lifted_count: number;
	no_change_count: number;
	dipped_count: number;
	not_enough_data_count: number;
	average_lift_percent: number | null;
}

export interface OverviewResult {
	stats: OverviewStats;
	summary: OverviewSummary;
	applied_products: OverviewAppliedProduct[];
}

export type OverviewAppliedProductsOrderBy = 'applied_date' | 'impact';

export interface OverviewState {
	updated_at?: string | null;
	result?: OverviewResult;
	applied_products_order_by?: OverviewAppliedProductsOrderBy;
}

export const overviewQueryKey: QueryKey = [ 'overview' ];

async function fetchOverview(): Promise< OverviewState > {
	return apiFetch< OverviewState >( { path: '/wcai-pa/v1/overview' } );
}

export async function postRefreshOverview(): Promise< OverviewState > {
	return apiFetch< OverviewState >( {
		path: '/wcai-pa/v1/overview',
		method: 'POST',
	} );
}

export interface OverviewAppliedProductsPage {
	products: OverviewAppliedProduct[];
	total: number;
}

const DEFAULT_APPLIED_PAGE_SIZE = 20;

async function postAppliedProductsOrder(
	orderBy: OverviewAppliedProductsOrderBy
): Promise< { applied_products_order_by: OverviewAppliedProductsOrderBy } > {
	return apiFetch< {
		applied_products_order_by: OverviewAppliedProductsOrderBy;
	} >( {
		path: '/wcai-pa/v1/overview/applied-products-order',
		method: 'POST',
		data: { order_by: orderBy },
	} );
}

async function fetchOverviewAppliedProductsPage( {
	orderBy,
	count,
	offset,
}: {
	orderBy: OverviewAppliedProductsOrderBy;
	count: number;
	offset: number;
} ): Promise< OverviewAppliedProductsPage > {
	const params = new URLSearchParams( {
		order_by: orderBy,
		count: String( count ),
		offset: String( offset ),
	} );
	return apiFetch< OverviewAppliedProductsPage >( {
		path: `/wcai-pa/v1/overview/applied-products?${ params.toString() }`,
	} );
}

export const overviewAppliedProductsInfiniteQuery = ( {
	orderBy,
	pageSize = DEFAULT_APPLIED_PAGE_SIZE,
}: {
	orderBy: OverviewAppliedProductsOrderBy;
	pageSize?: number;
} ) =>
	infiniteQueryOptions( {
		queryKey: [
			...overviewQueryKey,
			'applied-products',
			orderBy,
			pageSize,
		],
		queryFn: ( { pageParam = 0 } ) =>
			fetchOverviewAppliedProductsPage( {
				orderBy,
				count: pageSize,
				offset: pageParam as number,
			} ),
		initialPageParam: 0,
		getNextPageParam: ( lastPage, allPages ) => {
			const loaded = allPages.reduce(
				( sum, page ) => sum + page.products.length,
				0
			);
			return loaded < lastPage.total ? loaded : undefined;
		},
	} );

export const overviewQuery = () =>
	queryOptions( {
		queryKey: overviewQueryKey,
		queryFn: fetchOverview,
	} );

export const refreshOverviewMutation = () =>
	mutationOptions( {
		mutationFn: postRefreshOverview,
		onSuccess: () => {
			queryClient.invalidateQueries( { queryKey: overviewQueryKey } );
		},
	} );

export const updateAppliedProductsOrderMutation = () =>
	mutationOptions( {
		mutationFn: postAppliedProductsOrder,
		onMutate: async ( orderBy ) => {
			await queryClient.cancelQueries( { queryKey: overviewQueryKey } );
			const previous =
				queryClient.getQueryData< OverviewState >( overviewQueryKey );
			queryClient.setQueryData< OverviewState >(
				overviewQueryKey,
				( old ) =>
					old ? { ...old, applied_products_order_by: orderBy } : old
			);
			return { previous };
		},
		onError: ( _err, _orderBy, context ) => {
			if ( context?.previous ) {
				queryClient.setQueryData( overviewQueryKey, context.previous );
			}
		},
		onSuccess: ( data ) => {
			queryClient.setQueryData< OverviewState >(
				overviewQueryKey,
				( old ) =>
					old
						? {
								...old,
								applied_products_order_by:
									data.applied_products_order_by,
						  }
						: old
			);
		},
	} );
