import {
	mutationOptions,
	queryOptions,
	type QueryKey,
} from '@tanstack/react-query';
import { apiFetch } from './api-fetch';
import { queryClient } from '@/lib/query-client';

export interface ToneFeelResult {
	summary: string;
	traits: string[];
	fields?: string;
}

async function fetchToneFeel(): Promise< ToneFeelResult > {
	return apiFetch< ToneFeelResult >( {
		path: '/wcai-pa/v1/tone-feel',
	} );
}

async function saveToneFeel(
	tone: ToneFeelResult
): Promise< { success: boolean } > {
	return apiFetch< { success: boolean } >( {
		path: '/wcai-pa/v1/tone-feel',
		method: 'POST',
		data: { tone },
	} );
}

const toneFeelQueryKey: QueryKey = [ 'tone-feel' ];

export const toneFeelQuery = () =>
	queryOptions( {
		queryKey: toneFeelQueryKey,
		queryFn: fetchToneFeel,
	} );

export const saveToneFeelMutation = () =>
	mutationOptions( {
		mutationFn: saveToneFeel,
		onSuccess: () => {
			queryClient.invalidateQueries( { queryKey: toneFeelQueryKey } );
		},
	} );
