import { memo, useMemo, useState } from 'react';
import { dateI18n } from '@wordpress/date';
import { __, _n, sprintf } from '@wordpress/i18n';
import {
	Card,
	CardBody,
	CardHeader,
	Icon,
	__experimentalText as Text,
	__experimentalVStack as VStack,
	__experimentalHStack as HStack,
	__experimentalConfirmDialog as ConfirmDialog,
	Button,
	Notice,
} from '@wordpress/components';
import { chevronDown, chevronUp, external } from '@wordpress/icons';
import { useMutation } from '@tanstack/react-query';
import DiffViewer from 'react-diff-viewer-continued';
import TaxonomyDiffPreview from '../taxonomy-diff-preview';
import { isTaxonomyField, parseTaxonomyValue } from '@/lib/taxonomy';
import {
	revertSuggestionMutation,
	type ReviewedSuggestion,
	type ProductSuggestionField,
	type SuggestionFieldStatus,
} from '@/queries/suggestion';

import './style.scss';

const STATUS_ORDER: SuggestionFieldStatus[] = [
	'approved',
	'reverted',
	'rejected',
	'pending',
];

function collectStatuses(
	fields: ProductSuggestionField[]
): SuggestionFieldStatus[] {
	const unique = new Set( fields.map( ( f ) => f.status ).filter( Boolean ) );
	return STATUS_ORDER.filter( ( s ) => unique.has( s ) );
}

function fieldStatusLabel( status: SuggestionFieldStatus ): string {
	switch ( status ) {
		case 'approved':
			return __( 'Approved', 'wcai-pa' );
		case 'rejected':
			return __( 'Rejected', 'wcai-pa' );
		case 'reverted':
			return __( 'Reverted', 'wcai-pa' );
		default:
			return __( 'Pending', 'wcai-pa' );
	}
}

function deriveReviewedAtLabel(
	fields: ProductSuggestionField[],
	fallback: string
): string {
	const dates = fields
		.map( ( f ) => f.reviewed_at )
		.filter( ( d ): d is string => Boolean( d ) );
	const latest =
		dates.length > 0
			? dates.reduce( ( a, b ) => ( a > b ? a : b ) )
			: fallback;
	// Ensure UTC dates from the API are parsed as UTC so dateI18n converts to site timezone.
	const utcDate = latest.endsWith( 'Z' ) ? latest : latest + 'Z';
	const formatted = dateI18n( 'M j, Y g:i a', utcDate );
	const hasReverted = fields.some( ( f ) => f.status === 'reverted' );

	if ( hasReverted ) {
		return sprintf(
			/* translators: %s: formatted date and time */
			__( 'Reverted on %s', 'wcai-pa' ),
			formatted
		);
	}
	return sprintf(
		/* translators: %s: formatted date and time */
		__( 'Reviewed on %s', 'wcai-pa' ),
		formatted
	);
}

const ReadOnlyDiff = memo( function ReadOnlyDiff( {
	oldValue,
	newValue,
}: {
	oldValue: string;
	newValue: string;
} ) {
	return (
		<DiffViewer
			hideSummary
			disableWorker
			showDiffOnly={ false }
			oldValue={ oldValue }
			newValue={ newValue }
		/>
	);
} );

function ApprovedValuePreview( { field }: { field: ProductSuggestionField } ) {
	const approvedValue = field.value_approved ?? '';

	if ( isTaxonomyField( field.field ) ) {
		const terms = parseTaxonomyValue( approvedValue );

		return (
			<div className="wcai-pa-reviewed-card__approved-value">
				{ terms.length > 0 ? (
					<ul className="wcai-pa-reviewed-card__approved-taxonomy-list">
						{ terms.map( ( term ) => (
							<li key={ term.id }>{ term.name }</li>
						) ) }
					</ul>
				) : (
					<span>{ __( 'None', 'wcai-pa' ) }</span>
				) }
			</div>
		);
	}

	return (
		<div className="wcai-pa-reviewed-card__approved-value">
			{ approvedValue }
		</div>
	);
}

function ReviewedField( { field }: { field: ProductSuggestionField } ) {
	const status = field.status ?? 'pending';
	const isTaxonomy = isTaxonomyField( field.field );
	const showApprovedValue =
		field.value_approved !== null &&
		field.value_approved !== undefined &&
		field.value_approved !== field.new_value &&
		( status === 'approved' || status === 'reverted' );

	return (
		<VStack spacing={ 3 } className="wcai-pa-reviewed-card__field">
			<HStack justify="space-between" alignment="center">
				<Text weight="bold">{ field.field_label }</Text>
				<span
					className={ `wcai-pa-reviewed-card__field-status wcai-pa-reviewed-card__field-status--${ status }` }
				>
					{ fieldStatusLabel( status ) }
				</span>
			</HStack>

			{ field.reason && (
				<Text color="muted">
					{ __( 'Reason:', 'wcai-pa' ) } { field.reason }
				</Text>
			) }

			<div className="wcai-pa-reviewed-card__diff-container">
				{ isTaxonomy ? (
					<TaxonomyDiffPreview
						oldValue={ field.old_value }
						newValue={ field.new_value }
					/>
				) : (
					<ReadOnlyDiff
						oldValue={ field.old_value }
						newValue={ field.new_value }
					/>
				) }
			</div>

			{ showApprovedValue && (
				<VStack spacing={ 1 }>
					<Text weight="bold" color="muted">
						{ __( 'Approved value:', 'wcai-pa' ) }
					</Text>
					<ApprovedValuePreview field={ field } />
				</VStack>
			) }
		</VStack>
	);
}

interface ReviewedSuggestionCardProps {
	suggestion: ReviewedSuggestion;
}

export default function ReviewedSuggestionCard( {
	suggestion,
}: ReviewedSuggestionCardProps ) {
	const [ isOpen, setIsOpen ] = useState( false );
	const [ isConfirmOpen, setIsConfirmOpen ] = useState( false );
	const [ revertedAt, setRevertedAt ] = useState< string | null >( null );

	const revert = useMutation(
		revertSuggestionMutation( { suggestionId: suggestion.suggestion_id } )
	);

	const cardStatuses = useMemo(
		() => collectStatuses( suggestion.changed_fields ),
		[ suggestion.changed_fields ]
	);

	const canRevert = useMemo(
		() =>
			suggestion.changed_fields.some( ( f ) => f.status === 'approved' ),
		[ suggestion.changed_fields ]
	);

	const changesCount = suggestion.changed_fields.length;

	return (
		<Card size="medium">
			<button
				type="button"
				onClick={ () => setIsOpen( ! isOpen ) }
				className="wcai-pa-suggestion-card__toggle-button"
			>
				<CardHeader>
					<HStack justify="space-between">
						<HStack spacing={ 3 } style={ { width: 'auto' } }>
							<Text weight="bold">
								{ suggestion.product_name }
							</Text>
							{ suggestion.sku && suggestion.edit_url && (
								<a
									href={ suggestion.edit_url }
									target="_blank"
									rel="noreferrer"
									className="wcai-pa-suggestion-card__sku-link"
									onClick={ ( e ) => e.stopPropagation() }
								>
									{ suggestion.sku }
									<Icon icon={ external } size={ 16 } />
								</a>
							) }
							{ revertedAt ? (
								<span className="wcai-pa-reviewed-card__status-badge wcai-pa-reviewed-card__status-badge--reverted">
									{ sprintf(
										/* translators: %s: date string */
										__( 'Reverted on %s', 'wcai-pa' ),
										revertedAt
									) }
								</span>
							) : (
								cardStatuses.map( ( status ) => (
									<span
										key={ status }
										className={ `wcai-pa-reviewed-card__status-badge wcai-pa-reviewed-card__status-badge--${ status }` }
									>
										{ fieldStatusLabel( status ) }
									</span>
								) )
							) }
						</HStack>
						<HStack spacing={ 4 } style={ { width: 'auto' } }>
							<Text color="muted">
								{ sprintf(
									/* translators: %d: number of changes */
									_n(
										'%d change',
										'%d changes',
										changesCount,
										'wcai-pa'
									),
									changesCount
								) }
							</Text>
							{ isOpen ? (
								<Icon icon={ chevronUp } />
							) : (
								<Icon icon={ chevronDown } />
							) }
						</HStack>
					</HStack>
				</CardHeader>
			</button>
			{ isOpen && (
				<CardBody>
					<VStack spacing={ 6 }>
						{ suggestion.changed_fields.map( ( field ) => (
							<ReviewedField
								key={ field.field }
								field={ field }
							/>
						) ) }

						<HStack justify="space-between" alignment="center">
							<Text color="muted" size="small">
								{ deriveReviewedAtLabel(
									suggestion.changed_fields,
									suggestion.reviewed_at
								) }
							</Text>
							{ revertedAt ? (
								<Text color="muted" size="small">
									{ __( 'Revert complete', 'wcai-pa' ) }
								</Text>
							) : (
								canRevert && (
									<HStack
										spacing={ 4 }
										justify="flex-end"
										style={ { width: 'auto' } }
									>
										{ revert.error && (
											<Notice
												status="error"
												isDismissible={ false }
												className="wcai-pa-mutation-error-notice wcai-pa-mutation-error-notice--inline"
											>
												{ revert.error.message }
											</Notice>
										) }
										<Button
											variant="secondary"
											isDestructive
											onClick={ () =>
												setIsConfirmOpen( true )
											}
											isBusy={ revert.isPending }
											disabled={ revert.isPending }
										>
											{ revert.isPending
												? __( 'Reverting…', 'wcai-pa' )
												: __( 'Revert', 'wcai-pa' ) }
										</Button>
									</HStack>
								)
							) }
						</HStack>
					</VStack>

					<ConfirmDialog
						onConfirm={ () => {
							revert.mutate( undefined, {
								onSuccess: () => {
									setRevertedAt( dateI18n( 'M j, Y g:i a' ) );
								},
							} );
							setIsConfirmOpen( false );
						} }
						isOpen={ isConfirmOpen }
						onCancel={ () => setIsConfirmOpen( false ) }
					>
						{ sprintf(
							/* translators: %s: product name */
							__(
								'Are you sure you want to revert the approved changes for %s? This will restore the original values.',
								'wcai-pa'
							),
							suggestion.product_name
						) }
					</ConfirmDialog>
				</CardBody>
			) }
		</Card>
	);
}
