import { suggestionQuery } from '@/queries/suggestion';
import { useQuery } from '@tanstack/react-query';

import Loading from './loading';
import Suggestion from './suggestion';

export default function SuggestionCard( {
	defaultOpen,
	suggestionId,
}: {
	defaultOpen?: boolean;
	suggestionId: string;
} ) {
	const { data: suggestion } = useQuery(
		suggestionQuery( { suggestionId } )
	);

	if ( ! suggestion ) {
		return <Loading />;
	}

	return (
		<Suggestion defaultOpen={ defaultOpen } suggestionId={ suggestionId } />
	);
}
