import { queryClient } from '@/lib/query-client';
import {
	infiniteQueryOptions,
	mutationOptions,
	queryOptions,
} from '@tanstack/react-query';
import { apiFetch } from './api-fetch';
import { overviewQueryKey, postRefreshOverview } from './overview';
import { suggestionsQuery } from './suggestions';

export type ProductSuggestionFieldType =
	| 'text'
	| 'rich'
	| 'number'
	| 'taxonomy';

export type SuggestionFieldStatus =
	| 'pending'
	| 'approved'
	| 'rejected'
	| 'reverted';

export interface ProductSuggestionField {
	field: string;
	field_label: string;
	field_type: ProductSuggestionFieldType;
	old_value: string;
	new_value: string;
	confidence: number;
	reason: string;
	status?: SuggestionFieldStatus;
	reviewed_at?: string | null;
	is_edited?: boolean;
	value_approved?: string | null;
}

interface ProductSuggestionFieldDraft extends ProductSuggestionField {
	included?: boolean;
}

interface ProductSuggestion<
	T extends ProductSuggestionField = ProductSuggestionField,
> {
	product_id: string;
	product_name: string;
	sku?: string;
	edit_url?: string;
	changed_fields: T[];
}

export interface ReviewedSuggestion {
	suggestion_id: string;
	product_id: string;
	product_name: string;
	sku?: string;
	edit_url?: string;
	reviewed_at: string;
	changed_fields: ProductSuggestionField[];
}

export interface ReviewedSuggestionsResponse {
	suggestions: ReviewedSuggestion[];
	total: number;
}

function fetchSuggestion( {
	suggestionId,
}: {
	suggestionId: string;
} ): Promise< ProductSuggestion > {
	return apiFetch< ProductSuggestion >( {
		path: `/wcai-pa/v1/suggestions/${ suggestionId }`,
	} );
}

export const suggestionQuery = ( { suggestionId }: { suggestionId: string } ) =>
	queryOptions( {
		queryKey: [ 'suggestion', suggestionId ],
		queryFn: async ( { client } ) => {
			const suggestionFromTheServer = await fetchSuggestion( {
				suggestionId,
			} );

			const suggestionFromTheCache = client.getQueryData<
				ProductSuggestion< ProductSuggestionFieldDraft >
			>( [ 'suggestion', suggestionId ] );

			if ( ! suggestionFromTheCache ) {
				return suggestionFromTheServer;
			}

			return {
				...suggestionFromTheServer,
				changed_fields: suggestionFromTheServer.changed_fields.map(
					( field ) => {
						const fieldFromTheCache =
							suggestionFromTheCache.changed_fields.find(
								( f ) => f.field === field.field
							);

						return {
							...field,
							new_value:
								fieldFromTheCache?.new_value ?? field.new_value,
							included: fieldFromTheCache?.included,
						};
					}
				),
			};
		},
	} );

async function approveSuggestion( {
	suggestionId,
	approvedFields,
}: {
	suggestionId: string;
	approvedFields: Pick< ProductSuggestionField, 'field' | 'new_value' >[];
} ): Promise< void > {
	await apiFetch( {
		path: `/wcai-pa/v1/suggestions/${ suggestionId }`,
		method: 'POST',
		data: { status: 'approved', approved_fields: approvedFields },
	} );
}

export const CARD_EXIT_DURATION_MS = 400;

export const removeSuggestionFromCache = ( suggestionId: string ) => {
	queryClient.setQueryData( suggestionsQuery().queryKey, ( old ) => {
		if ( ! old ) {
			return old;
		}

		return {
			...old,
			suggestions: old.suggestions.filter(
				( suggestion ) => suggestion !== suggestionId
			),
		};
	} );

	queryClient.removeQueries( suggestionQuery( { suggestionId } ) );
	queryClient.invalidateQueries( suggestionsQuery() );
};

export const approveSuggestionMutation = ( {
	suggestionId,
}: {
	suggestionId: string;
} ) =>
	mutationOptions( {
		mutationFn: (
			approvedFields: Pick<
				ProductSuggestionField,
				'field' | 'new_value'
			>[]
		) =>
			approveSuggestion( {
				suggestionId,
				approvedFields,
			} ),
		onSuccess: () => {
			setTimeout(
				() => removeSuggestionFromCache( suggestionId ),
				CARD_EXIT_DURATION_MS
			);

			queryClient.invalidateQueries( { queryKey: overviewQueryKey } );
			void postRefreshOverview();
		},
	} );

async function rejectSuggestion( {
	suggestionId,
}: {
	suggestionId: string;
} ): Promise< void > {
	await apiFetch( {
		path: `/wcai-pa/v1/suggestions/${ suggestionId }`,
		method: 'POST',
		data: { status: 'rejected' },
	} );
}

export const rejectSuggestionMutation = ( {
	suggestionId,
}: {
	suggestionId: string;
} ) =>
	mutationOptions( {
		mutationFn: () => rejectSuggestion( { suggestionId } ),
		onSuccess: () => {
			setTimeout(
				() => removeSuggestionFromCache( suggestionId ),
				CARD_EXIT_DURATION_MS
			);

			queryClient.invalidateQueries( { queryKey: overviewQueryKey } );
			void postRefreshOverview();
		},
	} );

function fetchReviewedSuggestions( {
	count = 20,
	offset = 0,
}: {
	count?: number;
	offset?: number;
} ): Promise< ReviewedSuggestionsResponse > {
	return apiFetch< ReviewedSuggestionsResponse >( {
		path: `/wcai-pa/v1/suggestions-reviewed?count=${ count }&offset=${ offset }`,
	} );
}

export const reviewedSuggestionsInfiniteQuery = ( {
	pageSize = 20,
}: {
	pageSize?: number;
} = {} ) =>
	infiniteQueryOptions( {
		queryKey: [ 'reviewed-suggestions', pageSize ],
		queryFn: ( { pageParam = 0 } ) =>
			fetchReviewedSuggestions( { count: pageSize, offset: pageParam } ),
		initialPageParam: 0,
		getNextPageParam: ( lastPage, allPages ) => {
			const loaded = allPages.reduce(
				( sum, page ) => sum + page.suggestions.length,
				0
			);
			return loaded < lastPage.total ? loaded : undefined;
		},
	} );

async function revertSuggestion( {
	suggestionId,
}: {
	suggestionId: string;
} ): Promise< void > {
	await apiFetch( {
		path: `/wcai-pa/v1/suggestions/${ suggestionId }`,
		method: 'POST',
		data: { status: 'reverted' },
	} );
}

export const revertSuggestionMutation = ( {
	suggestionId,
}: {
	suggestionId: string;
} ) =>
	mutationOptions( {
		mutationFn: () => revertSuggestion( { suggestionId } ),
		onSuccess: () => {
			queryClient.invalidateQueries( {
				queryKey: [ 'reviewed-suggestions' ],
			} );
		},
	} );
