import { Button, Notice } from '@wordpress/components';
import { createInterpolateElement } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { useMutation } from '@tanstack/react-query';
import { connectUserMutation, acceptTosMutation } from '@/queries/connection';
import { config } from '@/lib/config';

import './style.scss';

export default function ConnectPrompt(): JSX.Element {
	const isConnected = config.isRegistered && config.isUserConnected;

	const {
		mutate: connect,
		isPending: isConnecting,
		error: connectError,
	} = useMutation( connectUserMutation() );

	const {
		mutate: acceptTos,
		isPending: isAccepting,
		error: acceptError,
	} = useMutation( acceptTosMutation() );

	const error = connectError || acceptError;
	const isBusy = isConnecting || isAccepting;

	const handleClick = () => {
		if ( isConnected ) {
			acceptTos( undefined, {
				onSuccess: () => {
					config.tosAccepted = true;
					window.location.reload();
				},
			} );
		} else {
			acceptTos( undefined, {
				onSuccess: () => {
					config.tosAccepted = true;
					connect( undefined, {
						onSuccess: ( authorizeUrl ) => {
							window.location.assign( authorizeUrl );
						},
					} );
				},
			} );
		}
	};

	return (
		<div className="wcai-pa-connect-prompt">
			<h2>{ __( 'Connect to WordPress.com', 'wcai-pa' ) }</h2>
			<p>
				{ __(
					'WooCommerce AI Product Advisor analyzes your product sales data to identify where you have the most room to improve, then uses AI to generate tailored suggestions. Connect your site to get started.',
					'wcai-pa'
				) }
			</p>
			<p>
				{ createInterpolateElement(
					__(
						'Your product data is sent to third-party AI providers to power suggestions. See our <guidelines>AI guidelines</guidelines>.',
						'wcai-pa'
					),
					{
						guidelines: (
							// eslint-disable-next-line jsx-a11y/anchor-has-content
							<a
								href={ config.aiGuidelinesUrl }
								target="_blank"
								rel="noreferrer noopener"
							/>
						),
					}
				) }
			</p>

			{ error && (
				<Notice status="error" isDismissible={ false }>
					{ error.message }
				</Notice>
			) }

			<p className="wcai-pa-connect-prompt__legal">
				{ createInterpolateElement(
					isConnected
						? __(
								'By continuing, you agree to the <tos>Terms of Service</tos> and acknowledge the <privacy>Privacy Policy</privacy>.',
								'wcai-pa'
						  )
						: __(
								'By connecting, you agree to the <tos>Terms of Service</tos> and acknowledge the <privacy>Privacy Policy</privacy>.',
								'wcai-pa'
						  ),
					{
						tos: (
							// eslint-disable-next-line jsx-a11y/anchor-has-content
							<a
								href={ config.tosUrl }
								target="_blank"
								rel="noreferrer noopener"
							/>
						),
						privacy: (
							// eslint-disable-next-line jsx-a11y/anchor-has-content
							<a
								href={ config.privacyUrl }
								target="_blank"
								rel="noreferrer noopener"
							/>
						),
					}
				) }
			</p>

			<div className="wcai-pa-connect-prompt__actions">
				<Button
					variant="primary"
					onClick={ handleClick }
					isBusy={ isBusy }
					disabled={ isBusy }
				>
					{ isConnected
						? __( 'Continue', 'wcai-pa' )
						: __( 'Connect', 'wcai-pa' ) }
				</Button>
			</div>
		</div>
	);
}
