import { __ } from '@wordpress/i18n';
import {
	Button,
	Spinner,
	__experimentalHStack as HStack,
	__experimentalVStack as VStack,
} from '@wordpress/components';
import { useToneFeelAnalysisPolling } from '@/hooks/use-tone-feel-analysis-polling';

interface Props {
	onRetry: () => void;
}

export default function LoadingStep( { onRetry }: Props ): JSX.Element {
	const { data: status, error } = useToneFeelAnalysisPolling();

	if ( status?.status === 'failed' || error ) {
		return (
			<VStack spacing={ 4 }>
				<span>
					{ __(
						'The tone analysis failed. Please try again.',
						'wcai-pa'
					) }
				</span>
				<Button
					variant="primary"
					onClick={ onRetry }
					style={ { alignSelf: 'start' } }
				>
					{ __( 'Retry', 'wcai-pa' ) }
				</Button>
			</VStack>
		);
	}

	return (
		<HStack justify="start" spacing={ 4 }>
			<Spinner style={ { margin: 0 } } />
			<p>{ __( 'Analyzing your store…', 'wcai-pa' ) }</p>
		</HStack>
	);
}
