import {
	Card,
	CardBody,
	__experimentalText as Text,
	__experimentalVStack as VStack,
	__experimentalHStack as HStack,
} from '@wordpress/components';
import { __, _n, sprintf } from '@wordpress/i18n';
import type {
	OverviewAppliedProduct,
	OverviewVerdict,
} from '@/queries/overview';

import './style.scss';

const VERDICT_VARIANT: Record< OverviewVerdict, string > = {
	lifted: 'wcai-pa-overview-applied-card__badge--lifted',
	no_change: 'wcai-pa-overview-applied-card__badge--no-change',
	dipped: 'wcai-pa-overview-applied-card__badge--dipped',
	not_enough_data: 'wcai-pa-overview-applied-card__badge--pending',
};

function verdictLabel( product: OverviewAppliedProduct ): string {
	switch ( product.verdict ) {
		case 'lifted':
			return sprintf(
				/* translators: %s: percent change, e.g. 18 */
				__( 'Lifted +%s%%', 'wcai-pa' ),
				formatMagnitude( product.magnitude_percent )
			);
		case 'dipped':
			return sprintf(
				/* translators: %s: percent change, e.g. 12 */
				__( 'Dipped −%s%%', 'wcai-pa' ),
				formatMagnitude( product.magnitude_percent )
			);
		case 'no_change':
			return __( 'No change', 'wcai-pa' );
		case 'not_enough_data':
		default:
			return __( 'Not enough data yet', 'wcai-pa' );
	}
}

function supportingLine( product: OverviewAppliedProduct ): string {
	const days = product.days_since_change;
	const daysLabel = sprintf(
		/* translators: %d: number of days */
		_n( '%d day', '%d days', days, 'wcai-pa' ),
		days
	);

	if ( product.verdict === 'not_enough_data' ) {
		// Either too early, or no pre-change baseline orders.
		if ( days < 7 ) {
			return sprintf(
				/* translators: %s: a phrase like "3 days" */
				__(
					'Only %s of data since change. Check back soon.',
					'wcai-pa'
				),
				daysLabel
			);
		}
		return __(
			'No pre-change order history to compare against.',
			'wcai-pa'
		);
	}

	const ordersLabel = sprintf(
		/* translators: 1: actual orders, 2: a phrase like "21 days", 3: expected orders */
		__( '%1$d orders in %2$s, vs ~%3$s expected.', 'wcai-pa' ),
		product.actual_orders,
		daysLabel,
		formatExpected( product.expected_orders )
	);
	return ordersLabel;
}

function formatMagnitude( value: number | null ): string {
	if ( value === null ) {
		return '0';
	}
	return Math.round( Math.abs( value ) ).toString();
}

function formatExpected( value: number | null ): string {
	if ( value === null ) {
		return '0';
	}
	return value < 1 && value > 0
		? value.toFixed( 1 )
		: Math.round( value ).toString();
}

interface Props {
	product: OverviewAppliedProduct;
}

export default function OverviewAppliedCard( { product }: Props ): JSX.Element {
	return (
		<Card size="small" className="wcai-pa-overview-applied-card">
			<CardBody>
				<HStack alignment="center" justify="space-between">
					<VStack spacing={ 1 }>
						<Text weight="bold">
							{ product.edit_url ? (
								<a
									className="wcai-pa-overview-applied-card__product-link"
									href={ product.edit_url }
								>
									{ product.product_name }
								</a>
							) : (
								product.product_name
							) }
						</Text>
						<Text variant="muted">
							{ supportingLine( product ) }
						</Text>
					</VStack>
					<span
						className={ `wcai-pa-overview-applied-card__badge ${
							VERDICT_VARIANT[ product.verdict ]
						}` }
					>
						{ verdictLabel( product ) }
					</span>
				</HStack>
			</CardBody>
		</Card>
	);
}
