import { __ } from '@wordpress/i18n';
import {
	Button,
	__experimentalVStack as VStack,
	__experimentalHStack as HStack,
	Spinner,
} from '@wordpress/components';
import ReviewedSuggestionCard from '@/components/reviewed-suggestion-card';
import { reviewedSuggestionsInfiniteQuery } from '@/queries/suggestion';
import { useInfiniteQuery } from '@tanstack/react-query';
import { useMemo } from 'react';

const REVIEWED_PAGE_SIZE = 20;

function ReviewedSuggestionsList() {
	const {
		data,
		isLoading,
		error,
		refetch,
		hasNextPage,
		fetchNextPage,
		isFetchingNextPage,
	} = useInfiniteQuery(
		reviewedSuggestionsInfiniteQuery( { pageSize: REVIEWED_PAGE_SIZE } )
	);

	const suggestions = useMemo(
		() => data?.pages.flatMap( ( page ) => page.suggestions ) ?? [],
		[ data ]
	);

	if ( isLoading ) {
		return (
			<HStack justify="start" spacing={ 4 }>
				<Spinner style={ { margin: 0 } } />
				<p style={ { margin: 0 } }>
					{ __( 'Loading history…', 'wcai-pa' ) }
				</p>
			</HStack>
		);
	}

	if ( error ) {
		return (
			<VStack spacing={ 4 }>
				<span>{ __( 'Failed to load history.', 'wcai-pa' ) }</span>
				<Button
					variant="primary"
					onClick={ () => refetch() }
					style={ { alignSelf: 'start' } }
				>
					{ __( 'Retry', 'wcai-pa' ) }
				</Button>
			</VStack>
		);
	}

	if ( suggestions.length === 0 ) {
		return <p>{ __( 'No reviewed suggestions yet.', 'wcai-pa' ) }</p>;
	}

	return (
		<VStack spacing={ 8 }>
			{ suggestions.map( ( suggestion ) => (
				<ReviewedSuggestionCard
					key={ suggestion.suggestion_id }
					suggestion={ suggestion }
				/>
			) ) }
			{ hasNextPage && (
				<Button
					variant="secondary"
					onClick={ () => fetchNextPage() }
					style={ { alignSelf: 'center' } }
					isBusy={ isFetchingNextPage }
					disabled={ isFetchingNextPage }
				>
					{ isFetchingNextPage
						? __( 'Loading…', 'wcai-pa' )
						: __( 'Load more', 'wcai-pa' ) }
				</Button>
			) }
		</VStack>
	);
}

export default function History(): JSX.Element {
	return (
		<div className="wcai-pa-screen">
			<h2>{ __( 'History', 'wcai-pa' ) }</h2>
			<ReviewedSuggestionsList />
		</div>
	);
}
