import ToneReview from '@/components/tone-review';
import { toneFeelQuery } from '@/queries/tone-feel';
import { Card, CardBody } from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { useQuery } from '@tanstack/react-query';
import ConnectionCard from '@/components/connection-card';

export default function Settings(): JSX.Element {
	const { data: initialData } = useQuery( toneFeelQuery() );

	return (
		<div>
			<h2>{ __( 'Settings', 'wcai-pa' ) }</h2>
			<Card>
				<CardBody>
					<h3 style={ { marginTop: 0 } }>
						{ __( "Your store's tone & feel", 'wcai-pa' ) }
					</h3>
					<ToneReview initialData={ initialData } />
				</CardBody>
			</Card>
			<ConnectionCard />
		</div>
	);
}
