import { __ } from '@wordpress/i18n';

const TITLES: Record< string, string > = {
	'/': __( 'Overview', 'wcai-pa' ),
	'/suggestions': __( 'Suggestions', 'wcai-pa' ),
	'/history': __( 'History', 'wcai-pa' ),
	'/settings': __( 'Settings', 'wcai-pa' ),
	'/onboarding': __( 'Setup', 'wcai-pa' ),
};

const SUFFIX = __( 'WooCommerce AI Product Advisor', 'wcai-pa' );

export function syncPageTitle( pathname: string ): void {
	const section = TITLES[ pathname ];
	document.title = section ? `${ section } ‹ ${ SUFFIX }` : SUFFIX;
}
