import {
	Button,
	CheckboxControl,
	Modal,
	__experimentalText as Text,
	__experimentalVStack as VStack,
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { useMemo, useState } from 'react';
import { parseTaxonomyValue } from '@/lib/taxonomy';

import './style.scss';

interface TaxonomyEditModalProps {
	productName: string;
	fieldLabel: string;
	newValue: string;
	onClose: () => void;
	onSave: ( value: string ) => void;
}

export default function TaxonomyEditModal( {
	productName,
	fieldLabel,
	newValue,
	onClose,
	onSave,
}: TaxonomyEditModalProps ) {
	const suggestedTerms = useMemo(
		() => parseTaxonomyValue( newValue ),
		[ newValue ]
	);

	const [ checkedIds, setCheckedIds ] = useState< Set< number > >(
		() => new Set( suggestedTerms.map( ( t ) => t.id ) )
	);

	const toggleTerm = ( termId: number ) => {
		setCheckedIds( ( prev ) => {
			const next = new Set( prev );
			if ( next.has( termId ) ) {
				next.delete( termId );
			} else {
				next.add( termId );
			}
			return next;
		} );
	};

	const handleSave = () => {
		const selectedTerms = suggestedTerms
			.filter( ( t ) => checkedIds.has( t.id ) )
			.map( ( { id, name } ) => ( { id, name } ) );

		onSave( JSON.stringify( selectedTerms ) );
	};

	return (
		<Modal
			size="large"
			onRequestClose={ onClose }
			title={ __( 'Edit field', 'wcai-pa' ) }
		>
			<ul style={ { marginTop: 0 } }>
				<li>
					<strong>{ __( 'Product:', 'wcai-pa' ) }</strong>{ ' ' }
					{ productName }
				</li>
				<li>
					<strong>{ __( 'Field:', 'wcai-pa' ) }</strong>{ ' ' }
					{ fieldLabel }
				</li>
			</ul>

			<VStack spacing={ 3 }>
				<Text weight="bold">
					{ __( 'Suggested categories', 'wcai-pa' ) }
				</Text>

				<div className="wcai-pa-taxonomy-edit__term-list">
					{ suggestedTerms.map( ( term ) => (
						<div
							key={ term.id }
							className="wcai-pa-taxonomy-edit__term-row"
						>
							<CheckboxControl
								__nextHasNoMarginBottom
								checked={ checkedIds.has( term.id ) }
								onChange={ () => toggleTerm( term.id ) }
								label={ term.name }
							/>
						</div>
					) ) }
				</div>
			</VStack>

			<div
				style={ {
					display: 'flex',
					justifyContent: 'flex-end',
					marginTop: '24px',
				} }
			>
				<Button
					__next40pxDefaultSize
					variant="primary"
					onClick={ handleSave }
				>
					{ __( 'Save', 'wcai-pa' ) }
				</Button>
			</div>
		</Modal>
	);
}
