import apiFetch from '@wordpress/api-fetch';
import { config } from '../lib/config';

// Bootstrap api-fetch with the site's REST root + nonce exactly once per page load.
// Doing this from module scope keeps the hook side-effect-free and survives re-mounts.
let apiFetchReady = false;

function ensureApiFetch( {
	apiRoot,
	apiNonce,
}: {
	apiRoot?: string;
	apiNonce?: string;
} ): void {
	if ( apiFetchReady ) {
		return;
	}
	if ( apiRoot ) {
		apiFetch.use( apiFetch.createRootURLMiddleware( apiRoot ) );
	}
	if ( apiNonce ) {
		apiFetch.use( apiFetch.createNonceMiddleware( apiNonce ) );
	}
	apiFetchReady = true;
}

ensureApiFetch( config );

export { apiFetch };
