export interface TaxonomyTerm {
	id: number;
	name: string;
}

const TAXONOMY_FIELDS = [ 'taxonomy_product_cat', 'taxonomy_product_tag' ];

export function isTaxonomyField( fieldName: string ): boolean {
	return TAXONOMY_FIELDS.includes( fieldName );
}

export function parseTaxonomyValue( value: string ): TaxonomyTerm[] {
	try {
		const parsed = JSON.parse( value );
		if ( ! Array.isArray( parsed ) ) {
			return [];
		}
		return parsed.filter(
			( item: unknown ): item is TaxonomyTerm =>
				typeof item === 'object' &&
				item !== null &&
				'id' in item &&
				'name' in item
		);
	} catch {
		return [];
	}
}
