import { queryOptions } from '@tanstack/react-query';
import { apiFetch } from './api-fetch';

interface ProductSuggestions {
	status: 'idle' | 'generating' | 'error' | 'no_products' | 'rate_limited';
	suggestions: string[];
}

function fetchSuggestions(): Promise< ProductSuggestions > {
	return apiFetch< ProductSuggestions >( {
		path: '/wcai-pa/v1/suggestions',
	} );
}

export const suggestionsQuery = () =>
	queryOptions( {
		queryKey: [ 'suggestions' ],
		queryFn: fetchSuggestions,
	} );
