import { queryClient } from '@/lib/query-client';
import { mutationOptions, queryOptions } from '@tanstack/react-query';
import { apiFetch } from './api-fetch';
import { config } from '@/lib/config';
import { __ } from '@wordpress/i18n';
import { suggestionsQuery } from './suggestions';

interface ConnectResponse {
	authorizeUrl?: string;
}

interface ConnectionSyncState {
	needsProductSync: boolean;
	syncStatus: 'in_sync' | 'sync_in_progress' | 'out_of_sync';
	title?: string;
	message?: string;
}

export const connectUserMutation = () =>
	mutationOptions( {
		mutationFn: async () => {
			const response = await apiFetch< ConnectResponse >( {
				path: '/jetpack/v4/connection/register',
				method: 'POST',
				data: {
					from: config.pluginSlug,
					plugin_slug: config.pluginSlug,
					redirect_uri: config.redirectUri,
				},
			} );

			if ( ! response?.authorizeUrl ) {
				throw new Error(
					__(
						'The registration response did not include an authorization URL.',
						'wcai-pa'
					)
				);
			}

			return response.authorizeUrl;
		},
	} );

export const acceptTosMutation = () =>
	mutationOptions( {
		mutationFn: async () =>
			apiFetch< { accepted: boolean } >( {
				path: '/wcai-pa/v1/tos/accept',
				method: 'POST',
			} ),
	} );

export const disconnectUserMutation = () =>
	mutationOptions( {
		mutationFn: async () =>
			apiFetch( {
				path: '/jetpack/v4/connection',
				method: 'POST',
				data: { isActive: false },
			} ),
	} );

const fetchConnectionSyncState = (): Promise< ConnectionSyncState > =>
	apiFetch< ConnectionSyncState >( {
		path: '/wcai-pa/v1/connection/sync',
	} );

export const connectionSyncStateQuery = () =>
	queryOptions( {
		queryKey: [ 'connection-sync-state' ],
		queryFn: fetchConnectionSyncState,
	} );

export const triggerConnectionSyncMutation = () =>
	mutationOptions( {
		mutationFn: async () =>
			apiFetch( {
				path: '/wcai-pa/v1/connection/sync',
				method: 'POST',
			} ),
		onSuccess: async () => {
			await Promise.all( [
				queryClient.invalidateQueries( connectionSyncStateQuery() ),
				queryClient.invalidateQueries( suggestionsQuery() ),
			] );
		},
	} );
