import { memo, useMemo } from 'react';
import {
	__experimentalVStack as VStack,
	__experimentalHStack as HStack,
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { parseTaxonomyValue, type TaxonomyTerm } from '@/lib/taxonomy';

import './style.scss';

interface TaxonomyDiffPreviewProps {
	oldValue: string;
	newValue: string;
}

function categorizeTerms( oldTerms: TaxonomyTerm[], newTerms: TaxonomyTerm[] ) {
	const oldIds = new Set( oldTerms.map( ( t ) => t.id ) );
	const newIds = new Set( newTerms.map( ( t ) => t.id ) );

	return {
		removed: oldTerms.filter( ( t ) => ! newIds.has( t.id ) ),
		kept: oldTerms.filter( ( t ) => newIds.has( t.id ) ),
		added: newTerms.filter( ( t ) => ! oldIds.has( t.id ) ),
	};
}

export default memo( function TaxonomyDiffPreview( {
	oldValue,
	newValue,
}: TaxonomyDiffPreviewProps ) {
	const oldTerms = useMemo(
		() => parseTaxonomyValue( oldValue ),
		[ oldValue ]
	);
	const newTerms = useMemo(
		() => parseTaxonomyValue( newValue ),
		[ newValue ]
	);
	const { removed, kept, added } = useMemo(
		() => categorizeTerms( oldTerms, newTerms ),
		[ oldTerms, newTerms ]
	);

	return (
		<HStack spacing={ 4 } alignment="top" className="wcai-pa-taxonomy-diff">
			<VStack spacing={ 1 } className="wcai-pa-taxonomy-diff__column">
				<ul className="wcai-pa-taxonomy-diff__list">
					{ oldTerms.map( ( term ) => (
						<li
							key={ term.id }
							className={
								removed.some( ( r ) => r.id === term.id )
									? 'wcai-pa-taxonomy-diff__term--removed'
									: ''
							}
						>
							{ term.name }
						</li>
					) ) }
					{ oldTerms.length === 0 && (
						<li className="wcai-pa-taxonomy-diff__term--empty">
							{ __( 'None', 'wcai-pa' ) }
						</li>
					) }
				</ul>
			</VStack>
			<VStack spacing={ 1 } className="wcai-pa-taxonomy-diff__column">
				<ul className="wcai-pa-taxonomy-diff__list">
					{ kept.map( ( term ) => (
						<li key={ term.id }>{ term.name }</li>
					) ) }
					{ added.map( ( term ) => (
						<li
							key={ term.id }
							className="wcai-pa-taxonomy-diff__term--added"
						>
							{ term.name }
						</li>
					) ) }
					{ kept.length === 0 && added.length === 0 && (
						<li className="wcai-pa-taxonomy-diff__term--empty">
							{ __( 'None', 'wcai-pa' ) }
						</li>
					) }
				</ul>
			</VStack>
		</HStack>
	);
} );
