import { useLayoutEffect, useState } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { useMutation } from '@tanstack/react-query';
import { config } from '../../lib/config';
import { triggerToneFeelAnalysisMutation } from '@/queries/tone-feel-analysis';
import ConnectStep from './steps/connect';
import LoadingStep from './steps/loading';
import ToneReviewStep from './steps/tone-review';
import SavedStep from './steps/saved';
import { useToneFeelAnalysisPolling } from '@/hooks/use-tone-feel-analysis-polling';
import { Notice, __experimentalVStack as VStack } from '@wordpress/components';
type Step = 'connect' | 'loading' | 'tone-review' | 'saved';

function getInitialStep(): Step {
	if (
		! config.tosAccepted ||
		! config.isRegistered ||
		! config.isUserConnected
	) {
		return 'connect';
	}
	return 'loading';
}

export default function Onboarding(): JSX.Element {
	const [ step, setStep ] = useState< Step >( getInitialStep );
	const { data: status } = useToneFeelAnalysisPolling( {
		enabled: step !== 'connect',
	} );
	const { mutate: triggerToneFeelAnalysis, error: retryError } = useMutation(
		triggerToneFeelAnalysisMutation()
	);

	useLayoutEffect( () => {
		if ( status?.status === 'stored' && status.result ) {
			setStep( 'tone-review' );
		}
	}, [ status ] );

	const handleRetry = () => {
		triggerToneFeelAnalysis( undefined, {
			onSuccess: () => setStep( 'loading' ),
		} );
	};

	const handleSaved = () => {
		config.onboardingComplete = true;
		setStep( 'saved' );
	};

	return (
		<div className="wcai-pa-screen">
			<h2>
				{ __( 'Set up WooCommerce AI Product Advisor', 'wcai-pa' ) }
			</h2>

			<VStack spacing={ 8 }>
				{ retryError && (
					<Notice
						status="error"
						isDismissible={ false }
						className="wcai-pa-mutation-error-notice"
					>
						{ retryError.message }
					</Notice>
				) }
				{ step === 'connect' && <ConnectStep /> }

				{ step === 'loading' && (
					<LoadingStep onRetry={ handleRetry } />
				) }

				{ step === 'tone-review' && status?.result && (
					<ToneReviewStep
						analysisResult={ status.result }
						onSaved={ handleSaved }
					/>
				) }

				{ step === 'saved' && <SavedStep /> }
			</VStack>
		</div>
	);
}
