import { useMemo } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { Card, CardBody } from '@wordpress/components';
import ToneReview from '@/components/tone-review';
import type { ToneFeelAnalysisResult } from '@/queries/tone-feel-analysis';

import './style.scss';

function formatLabel( key: string ): string {
	const label = key.replace( /_/g, ' ' );
	return label.charAt( 0 ).toUpperCase() + label.slice( 1 );
}

function flattenFields( fields: Record< string, string > ): string {
	return Object.entries( fields )
		.map( ( [ key, value ] ) => `${ formatLabel( key ) }: ${ value }` )
		.join( '\n\n' );
}

interface Props {
	analysisResult: ToneFeelAnalysisResult;
	onSaved: () => void;
}

export default function ToneReviewStep( {
	analysisResult,
	onSaved,
}: Props ): JSX.Element {
	const { current, recommended } = analysisResult;

	const initialData = useMemo(
		() => ( {
			summary: recommended.summary,
			traits: recommended.traits,
			fields: flattenFields( recommended.fields ),
		} ),
		[ recommended ]
	);

	return (
		<div className="wcai-pa-onboarding-step wcai-pa-onboarding-step--tone-review">
			<h3 className="wcai-pa-section-title">
				{ __( 'Current Analysis', 'wcai-pa' ) }
			</h3>
			<p className="wcai-pa-section-description">
				{ __(
					"Here's what we found by analyzing your existing product content.",
					'wcai-pa'
				) }
			</p>
			<Card className="wcai-pa-analysis-card">
				<CardBody>
					<p className="wcai-pa-analysis-summary">
						{ current.summary }
					</p>
					<div className="wcai-pa-traits">
						{ current.traits.map( ( trait ) => (
							<span key={ trait } className="wcai-pa-trait">
								{ trait }
							</span>
						) ) }
					</div>
				</CardBody>
			</Card>

			<h3 className="wcai-pa-section-title">
				{ __( 'Recommendations', 'wcai-pa' ) }
			</h3>
			<p className="wcai-pa-section-description">
				{ __(
					'Based on the analysis, here are our suggestions for your store. Feel free to edit them before saving.',
					'wcai-pa'
				) }
			</p>
			<Card className="wcai-pa-analysis-card">
				<CardBody>
					<ToneReview
						initialData={ initialData }
						onSaved={ onSaved }
					/>
				</CardBody>
			</Card>
		</div>
	);
}
