import {
	rejectSuggestionMutation,
	suggestionQuery,
} from '@/queries/suggestion';
import { useMutation, useSuspenseQuery } from '@tanstack/react-query';
import {
	Button,
	Notice,
	__experimentalConfirmDialog as ConfirmDialog,
} from '@wordpress/components';
import { __, sprintf } from '@wordpress/i18n';
import { useState } from 'react';

interface RejectSuggestionProps {
	suggestionId: string;
	onRejected?: () => void;
}

export default function RejectSuggestion( {
	suggestionId,
	onRejected,
}: RejectSuggestionProps ) {
	const [ isOpen, setIsOpen ] = useState( false );
	const {
		mutate: rejectSuggestion,
		isPending: isRejecting,
		error,
	} = useMutation( rejectSuggestionMutation( { suggestionId } ) );
	const { data: suggestion } = useSuspenseQuery(
		suggestionQuery( { suggestionId } )
	);

	const confirmPopupTitle = sprintf(
		/* translators: %s is the product name */
		__( 'Reject suggestion for product %s', 'wcai-pa' ),
		suggestion.product_name
	);

	return (
		<>
			<Button
				variant="secondary"
				isDestructive
				onClick={ () => setIsOpen( true ) }
			>
				{ __( 'Reject suggestion', 'wcai-pa' ) }
			</Button>
			<ConfirmDialog
				onConfirm={ () =>
					rejectSuggestion( undefined, {
						onSuccess: () => {
							setIsOpen( false );
							onRejected?.();
						},
					} )
				}
				isOpen={ isOpen }
				onCancel={ () => setIsOpen( false ) }
				isBusy={ isRejecting }
			>
				{ error && (
					<Notice
						status="error"
						isDismissible={ false }
						className="wcai-pa-mutation-error-notice"
					>
						{ error.message }
					</Notice>
				) }
				{ confirmPopupTitle }
			</ConfirmDialog>
		</>
	);
}
