import { createInterpolateElement } from '@wordpress/element';
import { __, sprintf } from '@wordpress/i18n';
import {
	Button,
	__experimentalVStack as VStack,
	__experimentalHStack as HStack,
	Notice,
	Spinner,
} from '@wordpress/components';
import { CONTACT_LIMIT_EXTENSION_URL } from '@/lib/constants';
import SuggestionCard from '@/components/suggestion-card';
import { overviewQuery } from '@/queries/overview';
import { suggestionsQuery } from '@/queries/suggestions';
import { useQuery } from '@tanstack/react-query';

const MAX_SUGGESTIONS_TO_DISPLAY = 20;
const POLL_INTERVAL_MS = 3_000;

function RateLimitedNotice() {
	const { data: overviewState } = useQuery( overviewQuery() );

	const weeklyLimit =
		overviewState?.result?.stats.weekly_suggestions_limit ?? 200;

	return (
		<Notice status="warning" isDismissible={ false }>
			{ createInterpolateElement(
				sprintf(
					// translators: 1: weekly AI suggestion cap for this site. <a> opens the contact / extension request link.
					__(
						"You've reached this site's weekly limit of %1$d AI suggestions. New suggestions will be available next week. <a>Contact us</a> to request an extension.",
						'wcai-pa'
					),
					weeklyLimit
				),
				{
					a: (
						// eslint-disable-next-line jsx-a11y/anchor-has-content
						<a
							href={ CONTACT_LIMIT_EXTENSION_URL }
							target="_blank"
							rel="noreferrer"
						/>
					),
				}
			) }
		</Notice>
	);
}

function SuggestionsList() {
	const {
		data: suggestions,
		refetch,
		error,
	} = useQuery( {
		...suggestionsQuery(),
		refetchInterval: ( query ) => {
			const errorCode = ( query.state.error as { code?: string } )?.code;
			if (
				errorCode === 'sync_in_progress' ||
				errorCode === 'out_of_sync'
			) {
				return POLL_INTERVAL_MS;
			}

			if ( query.state.data?.status !== 'generating' ) {
				return false;
			}

			return POLL_INTERVAL_MS;
		},
	} );

	if ( suggestions?.suggestions.length ) {
		return (
			<VStack spacing={ 8 }>
				{ suggestions.suggestions
					.slice( 0, MAX_SUGGESTIONS_TO_DISPLAY )
					.map( ( suggestionId, index ) => (
						<SuggestionCard
							key={ suggestionId }
							defaultOpen={ index < 3 }
							suggestionId={ suggestionId }
						/>
					) ) }
			</VStack>
		);
	}

	if ( suggestions?.status === 'no_products' ) {
		return (
			<p>
				{ __(
					'All existing products have been processed. New suggestions will appear here when new products are added.',
					'wcai-pa'
				) }
			</p>
		);
	}

	if ( suggestions?.status === 'rate_limited' ) {
		return <RateLimitedNotice />;
	}

	if ( suggestions?.status === 'generating' ) {
		return (
			<HStack justify="start" spacing={ 4 }>
				<Spinner style={ { margin: 0 } } />
				<p style={ { margin: 0 } }>
					{ __( 'Generating suggestions…', 'wcai-pa' ) }
				</p>
			</HStack>
		);
	}

	if ( ! suggestions && ! error ) {
		return (
			<HStack justify="start" spacing={ 4 }>
				<Spinner style={ { margin: 0 } } />
				<p style={ { margin: 0 } }>
					{ __( 'Loading suggestions…', 'wcai-pa' ) }
				</p>
			</HStack>
		);
	}

	const errorCode = ( error as { code?: string } )?.code;
	if ( errorCode === 'sync_in_progress' || errorCode === 'out_of_sync' ) {
		return null;
	}

	return (
		<VStack spacing={ 4 }>
			<span>
				{ __(
					'Failed to generate suggestions. Please try again.',
					'wcai-pa'
				) }
			</span>
			<Button
				variant="primary"
				onClick={ () => refetch() }
				style={ { alignSelf: 'start' } }
			>
				{ __( 'Retry', 'wcai-pa' ) }
			</Button>
		</VStack>
	);
}

export default function Suggestions(): JSX.Element {
	return (
		<div className="wcai-pa-screen">
			<h2>{ __( 'Suggestions', 'wcai-pa' ) }</h2>
			<SuggestionsList />
		</div>
	);
}
