interface AppConfig {
	apiRoot: string;
	apiNonce: string;
	isRegistered: boolean;
	isUserConnected: boolean;
	pluginSlug: string;
	redirectUri: string;
	tosUrl: string;
	privacyUrl: string;
	aiGuidelinesUrl: string;
	onboardingComplete: boolean;
	tosAccepted: boolean;
}

interface WindowWithConfig {
	wcaiPoConfig?: {
		connection: Omit<
			AppConfig,
			'apiRoot' | 'apiNonce' | 'onboardingComplete' | 'tosAccepted'
		>;
		apiRoot: string;
		apiNonce: string;
		onboardingComplete?: boolean;
		tosAccepted?: boolean;
	};
}

declare global {
	interface Window extends WindowWithConfig {}
}

function readConfig(): AppConfig {
	const config = window.wcaiPoConfig;

	if ( ! config ) {
		throw new Error( 'wcaiPoConfig is not defined' );
	}

	return {
		...config,
		...config.connection,
		onboardingComplete: config.onboardingComplete ?? false,
		tosAccepted: config.tosAccepted ?? false,
	};
}

export const config = readConfig();
