import { Card, CardBody, Spinner } from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { useNavigate } from '@tanstack/react-router';
import type { ReactNode } from 'react';
import type { OverviewStats } from '@/queries/overview';

interface Props {
	stats: OverviewStats;
	pendingSuggestionsCount: number | null;
	pendingLoading?: boolean;
}

// `null` indicates the source of truth (WPCOM stats option) wasn't reachable;
// we render "N/A" rather than 0 so the difference is legible in the UI.
const NA_LABEL = __( 'N/A', 'wcai-pa' );

function formatCount( value: number | null ): string {
	return value === null ? NA_LABEL : value.toString();
}

function formatPercent( value: number | null ): string {
	if ( value === null || Number.isNaN( value ) ) {
		return NA_LABEL;
	}
	return `${ Math.round( value * 100 ) }%`;
}

export default function OverviewStatCards( {
	stats,
	pendingSuggestionsCount,
	pendingLoading = false,
}: Props ): JSX.Element {
	const navigate = useNavigate();

	const cards: Array< {
		label: string;
		value: ReactNode;
		to?: string;
	} > = [
		{
			label: pendingLoading
				? __( 'Generating suggestions…', 'wcai-pa' )
				: __( 'Pending suggestions', 'wcai-pa' ),
			value: pendingLoading ? (
				<Spinner style={ { margin: 0 } } />
			) : (
				formatCount( pendingSuggestionsCount )
			),
			to: '/suggestions',
		},
		{
			label: __( 'Applied (7d)', 'wcai-pa' ),
			value: formatCount( stats.applied_7d ),
			to: '/history',
		},
		{
			label: __( 'Approval rate (30d)', 'wcai-pa' ),
			value: formatPercent( stats.approval_rate_30d ),
		},
		{
			label: __( 'Total suggestions', 'wcai-pa' ),
			value: formatCount( stats.total_suggestions ),
		},
	];

	return (
		<div className="wcai-pa-overview-stat-cards">
			{ cards.map( ( card ) => {
				const content = (
					<CardBody>
						<div className="wcai-pa-overview-stat-cards__value">
							{ card.value }
						</div>
						<div className="wcai-pa-overview-stat-cards__label">
							{ card.label }
						</div>
					</CardBody>
				);

				return card.to ? (
					<Card
						key={ card.label }
						size="small"
						className="wcai-pa-overview-stat-cards__card--clickable"
						onClick={ () => navigate( { to: card.to } ) }
					>
						{ content }
					</Card>
				) : (
					<Card key={ card.label } size="small">
						{ content }
					</Card>
				);
			} ) }
		</div>
	);
}
