import { Card, CardBody, ExternalLink } from '@wordpress/components';
import { __, sprintf } from '@wordpress/i18n';
import { type OverviewStats } from '@/queries/overview';
import { CONTACT_LIMIT_EXTENSION_URL } from '@/lib/constants';

import './style.scss';

export default function WeeklyUsage( {
	stats,
}: {
	stats: OverviewStats;
} ): JSX.Element | null {
	const { weekly_suggestions_used: used, weekly_suggestions_limit: limit } =
		stats;

	if ( used === null || limit === null || used < 0.5 * limit ) {
		return null;
	}

	return (
		<Card size="small" className="wcai-pa-weekly-usage">
			<CardBody>
				<p className="wcai-pa-weekly-usage__text">
					{ used >= limit
						? __( 'Weekly suggetions limit reached.', 'wcai-pa' )
						: sprintf(
								// translators: 1: used suggestions, 2: weekly limit.
								__(
									'%1$d of %2$d weekly suggestions used.',
									'wcai-pa'
								),
								used,
								limit
						  ) }
					<ExternalLink
						href={ CONTACT_LIMIT_EXTENSION_URL }
						target="_blank"
						rel="noreferrer"
					>
						{ __( 'Request an extension', 'wcai-pa' ) }
					</ExternalLink>
				</p>
			</CardBody>
		</Card>
	);
}
