export function syncSidebarHighlight( pathname: string ): void {
	const toplevel = document.querySelector(
		'#adminmenu .toplevel_page_wcai-pa'
	);
	if ( ! toplevel ) {
		return;
	}
	toplevel.querySelectorAll( '.wp-submenu > li' ).forEach( ( li ) => {
		const link = li.querySelector( 'a' );
		if ( ! link ) {
			return;
		}
		const href = link.getAttribute( 'href' ) || '';
		const match = href.match( /#(\/.+)$/ );
		// Overview link has no hash fragment; all others do.
		const linkPath = match ? match[ 1 ] : '/';
		const isActive = linkPath === pathname;
		li.classList.toggle( 'current', isActive );
		link.classList.toggle( 'current', isActive );
	} );
}
