import { useInfiniteQuery, useMutation, useQuery } from '@tanstack/react-query';
import {
	Button,
	Notice,
	SelectControl,
	Spinner,
	__experimentalHStack as HStack,
	__experimentalVStack as VStack,
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { useMemo } from 'react';
import {
	overviewAppliedProductsInfiniteQuery,
	overviewQuery,
	refreshOverviewMutation,
	updateAppliedProductsOrderMutation,
	type OverviewAppliedProductsOrderBy,
} from '@/queries/overview';
import { suggestionsQuery } from '@/queries/suggestions';
import OverviewStatCards from '@/components/overview-stat-cards';
import OverviewSummary from '@/components/overview-summary';
import OverviewAppliedCard from '@/components/overview-applied-card';
import WeeklyUsage from './weekly-usage';
import './style.scss';

const APPLIED_PAGE_SIZE = 20;
const SUGGESTIONS_POLL_INTERVAL_MS = 3_000;

function AppliedSuggestionsList( {
	sortBy,
}: {
	sortBy: OverviewAppliedProductsOrderBy;
} ): JSX.Element {
	const {
		data,
		isLoading,
		error,
		refetch,
		hasNextPage,
		fetchNextPage,
		isFetchingNextPage,
	} = useInfiniteQuery(
		overviewAppliedProductsInfiniteQuery( {
			orderBy: sortBy,
			pageSize: APPLIED_PAGE_SIZE,
		} )
	);

	const products = useMemo(
		() => data?.pages.flatMap( ( page ) => page.products ) ?? [],
		[ data ]
	);

	if ( isLoading ) {
		return (
			<HStack justify="start" spacing={ 4 }>
				<Spinner style={ { margin: 0 } } />
				<p style={ { margin: 0 } }>
					{ __( 'Loading applied changes…', 'wcai-pa' ) }
				</p>
			</HStack>
		);
	}

	if ( error ) {
		return (
			<VStack spacing={ 4 }>
				<span>
					{ __( 'Failed to load applied changes.', 'wcai-pa' ) }
				</span>
				<Button
					variant="primary"
					onClick={ () => refetch() }
					style={ { alignSelf: 'start' } }
				>
					{ __( 'Retry', 'wcai-pa' ) }
				</Button>
			</VStack>
		);
	}

	if ( products.length === 0 ) {
		return (
			<p className="wcai-pa-overview__empty">
				{ __(
					'No applied suggestions yet. Approve a suggestion to start tracking changes.',
					'wcai-pa'
				) }
			</p>
		);
	}

	return (
		<VStack spacing={ 8 }>
			<div className="wcai-pa-overview__applied-list">
				{ products.map( ( product ) => (
					<OverviewAppliedCard
						key={ product.product_id }
						product={ product }
					/>
				) ) }
			</div>
			{ hasNextPage && (
				<Button
					variant="secondary"
					onClick={ () => fetchNextPage() }
					style={ { alignSelf: 'center' } }
					isBusy={ isFetchingNextPage }
					disabled={ isFetchingNextPage }
				>
					{ isFetchingNextPage
						? __( 'Loading…', 'wcai-pa' )
						: __( 'Load more', 'wcai-pa' ) }
				</Button>
			) }
		</VStack>
	);
}

export default function Overview(): JSX.Element {
	const query = useQuery( overviewQuery() );

	const refresh = useMutation( refreshOverviewMutation() );

	const saveAppliedOrder = useMutation(
		updateAppliedProductsOrderMutation()
	);

	const operationError = refresh.error ?? saveAppliedOrder.error;

	const appliedSortBy: OverviewAppliedProductsOrderBy =
		query.data?.applied_products_order_by ?? 'applied_date';

	const result = query.data?.result;
	const lastUpdatedAt = query.data?.updated_at ?? null;

	const suggestions = useQuery( {
		...suggestionsQuery(),
		refetchInterval: ( q ) => {
			const errorCode = ( q.state.error as { code?: string } )?.code;
			if (
				errorCode === 'sync_in_progress' ||
				errorCode === 'out_of_sync'
			) {
				return SUGGESTIONS_POLL_INTERVAL_MS;
			}
			return q.state.data?.status === 'generating'
				? SUGGESTIONS_POLL_INTERVAL_MS
				: false;
		},
	} );

	const header = (
		<Header
			lastUpdatedAt={ lastUpdatedAt }
			onRefresh={ () => refresh.mutate() }
			isPending={ refresh.isPending }
		/>
	);

	if ( query.isError ) {
		return (
			<section>
				{ header }
				<div className="wcai-pa-overview__error">
					{ __( 'Could not load overview data.', 'wcai-pa' ) }
				</div>
			</section>
		);
	}

	if ( ! result && query.isLoading ) {
		return (
			<section>
				{ header }
				<p>{ __( 'Loading…', 'wcai-pa' ) }</p>
			</section>
		);
	}

	if ( ! result ) {
		return (
			<section>
				{ header }
				<p>{ __( 'No data yet.', 'wcai-pa' ) }</p>
			</section>
		);
	}

	const hasApplied = result.summary.total_changed > 0;

	const getPendingSuggestionsCount = () => {
		// Only use the pending count if there are pending suggestions and it's greater than 0.
		if ( result.stats.pending ) {
			return result.stats.pending;
		}

		// Otherwise, use the pending suggestions count from the suggestions query.
		return suggestions.data?.suggestions.length ?? null;
	};

	return (
		<section>
			{ header }
			{ operationError && (
				<Notice
					status="error"
					isDismissible={ false }
					className="wcai-pa-mutation-error-notice"
				>
					{ operationError.message }
				</Notice>
			) }

			<OverviewStatCards
				stats={ result.stats }
				pendingSuggestionsCount={ getPendingSuggestionsCount() }
				pendingLoading={ suggestions.data?.status === 'generating' }
			/>
			<WeeklyUsage stats={ result.stats } />
			<HStack
				className="wcai-pa-overview__applied-heading"
				justify="space-between"
				alignment="center"
			>
				<h3 className="wcai-pa-overview__applied-title">
					{ __( 'Applied changes', 'wcai-pa' ) }
				</h3>
				{ hasApplied && (
					<SelectControl
						className="wcai-pa-overview__applied-sort"
						label={ __( 'Order by', 'wcai-pa' ) }
						hideLabelFromVision
						value={ appliedSortBy }
						options={ [
							{
								label: __( 'Applied date', 'wcai-pa' ),
								value: 'applied_date',
							},
							{
								label: __( 'Impact (lift / dip)', 'wcai-pa' ),
								value: 'impact',
							},
						] }
						onChange={ ( value ) =>
							saveAppliedOrder.mutate(
								value === 'impact' ? 'impact' : 'applied_date'
							)
						}
					/>
				) }
			</HStack>
			<OverviewSummary summary={ result.summary } />
			{ ! hasApplied ? (
				<p className="wcai-pa-overview__empty">
					{ __(
						'No applied suggestions yet. Approve a suggestion to start tracking changes.',
						'wcai-pa'
					) }
				</p>
			) : (
				<AppliedSuggestionsList sortBy={ appliedSortBy } />
			) }
		</section>
	);
}

function Header( {
	lastUpdatedAt,
	onRefresh,
	isPending,
}: {
	lastUpdatedAt: string | null;
	onRefresh: () => void;
	isPending: boolean;
} ): JSX.Element {
	return (
		<header className="wcai-pa-overview__header">
			<h2>{ __( 'Overview', 'wcai-pa' ) }</h2>
			<span className="wcai-pa-overview__updated">
				{ __( 'Last updated:', 'wcai-pa' ) }{ ' ' }
				{ formatLastUpdated( lastUpdatedAt ) }
			</span>
			<Button
				className="wcai-pa-overview__refresh-button"
				variant="secondary"
				onClick={ onRefresh }
				disabled={ isPending }
				isBusy={ isPending }
			>
				{ __( 'Refresh', 'wcai-pa' ) }
			</Button>
		</header>
	);
}

function formatLastUpdated( iso: string | null ): string {
	if ( ! iso ) {
		return __( 'never', 'wcai-pa' );
	}
	const date = new Date( iso );
	if ( Number.isNaN( date.getTime() ) ) {
		return __( 'never', 'wcai-pa' );
	}
	return date.toLocaleString();
}
