import { config } from '@/lib/config';
import {
	connectionSyncStateQuery,
	triggerConnectionSyncMutation,
} from '@/queries/connection';
import { useMutation, useQuery } from '@tanstack/react-query';
import { __ } from '@wordpress/i18n';
import {
	Notice,
	__experimentalText as Text,
	__experimentalVStack as VStack,
} from '@wordpress/components';

export default function DataOutOfSyncNotice() {
	const connectedAndOnboarded =
		config.isRegistered &&
		config.isUserConnected &&
		!! config.onboardingComplete;

	const { data: syncState, isLoading: isSyncStateLoading } = useQuery( {
		...connectionSyncStateQuery(),
		refetchInterval: ( query ) => {
			if ( true === query.state.data?.needsProductSync ) {
				return 3000;
			}

			return false;
		},
		enabled: connectedAndOnboarded,
	} );

	const {
		mutate: triggerSyncNow,
		isPending: isTriggeringSync,
		error,
	} = useMutation( triggerConnectionSyncMutation() );

	const shouldShowSyncNotice =
		connectedAndOnboarded && syncState?.needsProductSync;

	if ( ! shouldShowSyncNotice ) {
		return null;
	}

	const showSyncButton = syncState?.syncStatus === 'out_of_sync';

	return (
		<div style={ { marginTop: '16px' } }>
			<Notice
				status="warning"
				isDismissible={ false }
				actions={
					showSyncButton
						? [
								{
									label: __( 'Sync now', 'wcai-pa' ),
									onClick: () => triggerSyncNow(),
									disabled:
										isTriggeringSync || isSyncStateLoading,
									variant: 'primary',
								},
						  ]
						: []
				}
			>
				<VStack>
					{ error && (
						<Notice
							status="error"
							isDismissible={ false }
							className="wcai-pa-mutation-error-notice"
						>
							{ error.message }
						</Notice>
					) }
					<Text weight="bold">{ syncState.title }</Text>
					<Text>{ syncState.message }</Text>
				</VStack>
			</Notice>
		</div>
	);
}
