import {
	Card,
	CardBody,
	CardHeader,
	Icon,
	__experimentalText as Text,
	Button,
	__experimentalVStack as VStack,
	__experimentalHStack as HStack,
	CheckboxControl,
	Notice,
} from '@wordpress/components';
import { DataForm } from '@wordpress/dataviews/wp';
import { chevronDown, chevronUp, external } from '@wordpress/icons';
import type { Field, Form } from '@wordpress/dataviews/wp';
import { memo, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { __, _n, sprintf } from '@wordpress/i18n';
import DiffViewer from 'react-diff-viewer-continued';
import EditFieldModal from '../edit-field-modal';
import TaxonomyDiffPreview from '../taxonomy-diff-preview';
import TaxonomyEditModal from '../taxonomy-edit-modal';
import { isTaxonomyField } from '@/lib/taxonomy';
import {
	useMutation,
	useQueryClient,
	useSuspenseQuery,
} from '@tanstack/react-query';
import {
	approveSuggestionMutation,
	CARD_EXIT_DURATION_MS,
	suggestionQuery,
} from '@/queries/suggestion';
import RejectSuggestion from '../reject-suggestion';
import './style.scss';

interface SuggestionCardProps {
	defaultOpen?: boolean;
	suggestionId: string;
}

const SuggestionDiffPreview = memo( function SuggestionDiffPreview( {
	oldValue,
	newValue,
}: {
	oldValue: string;
	newValue: string;
} ) {
	return (
		<DiffViewer
			hideSummary
			disableWorker
			showDiffOnly={ false }
			oldValue={ oldValue }
			newValue={ newValue }
		/>
	);
} );

interface SuggestionFormData {
	[ key: string ]: {
		included: boolean;
		new_value: string;
	};
}

export default function SuggestionCard( {
	defaultOpen = true,
	suggestionId,
}: SuggestionCardProps ) {
	const [ isOpen, setIsOpen ] = useState( defaultOpen );
	const [ isExiting, setIsExiting ] = useState( false );

	useLayoutEffect( () => {
		setIsOpen( defaultOpen );
	}, [ defaultOpen ] );

	const { data: suggestion } = useSuspenseQuery(
		suggestionQuery( { suggestionId } )
	);

	const approveSuggestion = useMutation(
		approveSuggestionMutation( { suggestionId } )
	);

	const queryClient = useQueryClient();

	const formData = useMemo< SuggestionFormData >( () => {
		return suggestion.changed_fields.reduce(
			( acc: SuggestionFormData, field ) => {
				acc[ field.field ] = {
					included: field.included ?? true,
					new_value: field.new_value,
				};

				return acc;
			},
			{}
		);
	}, [ suggestion.changed_fields ] );

	const isPendingRef = useRef( approveSuggestion.isPending );
	isPendingRef.current = approveSuggestion.isPending;

	const suggestionRef = useRef( suggestion );
	suggestionRef.current = suggestion;

	const fields = useMemo< Array< Field< SuggestionFormData > > >(
		() =>
			suggestionRef.current.changed_fields
				.map( ( field ): Field< SuggestionFormData >[] => {
					return [
						{
							id: `${ field.field }_included`,
							type: 'boolean' as const,
							Edit: ( { data, onChange } ) => (
								<CheckboxControl
									checked={ data[ field.field ].included }
									disabled={ isPendingRef.current }
									onChange={ ( value ) =>
										onChange( {
											...data,
											[ field.field ]: {
												...data[ field.field ],
												included: value,
											},
										} )
									}
								/>
							),
						},
						{
							id: `${ field.field }_reason`,
							Edit: () => <Text>Reason: { field.reason }</Text>,
						},
						{
							id: field.field,
							Edit: ( { data, onChange } ) => {
								const [ isEditingOpen, setIsEditingOpen ] =
									useState( false );

								const onClose = () => {
									setIsEditingOpen( false );
								};

								const saveNewValue = ( newValue: string ) => {
									onChange( {
										...data,
										[ field.field ]: {
											...data[ field.field ],
											new_value: newValue,
											included: true,
										},
									} );

									onClose();
								};

								const oldValue = field.old_value;
								const newValue = data[ field.field ].new_value;
								const suggestionKey = `${ suggestionRef.current.product_name }-${ field.field }-${ oldValue }-${ newValue }`;
								const isTaxonomy = isTaxonomyField(
									field.field
								);

								return (
									<>
										<div
											role="button"
											className="wcai-pa-suggestion-card__diff-viewer-button"
											onClick={ () => {
												if ( isPendingRef.current ) {
													return;
												}

												setIsEditingOpen( true );
											} }
											onKeyDown={ ( event ) => {
												if (
													event.key === 'Enter' &&
													! isPendingRef.current
												) {
													setIsEditingOpen( true );
												}
											} }
											tabIndex={ 0 }
										>
											<div className="wcai-pa-suggestion-card__diff-viewer-container">
												{ isTaxonomy ? (
													<TaxonomyDiffPreview
														key={ suggestionKey }
														oldValue={ oldValue }
														newValue={ newValue }
													/>
												) : (
													<SuggestionDiffPreview
														key={ suggestionKey }
														oldValue={ oldValue }
														newValue={ newValue }
													/>
												) }
											</div>
										</div>
										{ isEditingOpen &&
											( isTaxonomy ? (
												<TaxonomyEditModal
													key={ suggestionKey }
													productName={
														suggestionRef.current
															.product_name
													}
													fieldLabel={
														field.field_label
													}
													newValue={ newValue }
													onClose={ onClose }
													onSave={ saveNewValue }
												/>
											) : (
												<EditFieldModal
													key={ suggestionKey }
													productName={
														suggestionRef.current
															.product_name
													}
													fieldLabel={
														field.field_label
													}
													fieldType={
														field.field_type
													}
													newValue={ newValue }
													onClose={ onClose }
													onSave={ saveNewValue }
												/>
											) ) }
									</>
								);
							},
						},
					];
				} )
				.flat(),
		[]
	);

	const form = useMemo< Form >( () => {
		return {
			fields: suggestionRef.current.changed_fields.map( ( field ) => {
				return {
					id: field.field,
					label: field.field_label,
					children: [
						{
							id: `${ field.field }_reason`,
							children: [ `${ field.field }_reason` ],
						},
						{
							id: `${ field.field }_diff`,
							layout: {
								type: 'row',
								styles: {
									[ field.field ]: { flex: 1 },
									[ `${ field.field }_included` ]: {
										flex: 0,
										height: '22px',
										alignSelf: 'end',
										display: 'flex',
										alignItems: 'center',
									},
								},
							},
							children: [
								field.field,
								`${ field.field }_included`,
							],
						},
					],
				};
			} ),
		};
	}, [] );

	const includedChangesMessage = useMemo( () => {
		const includedChanges = Object.values( formData ?? {} ).filter(
			( field ) => field && field.included
		).length;

		if ( includedChanges === 0 ) {
			return null;
		}

		return sprintf(
			/* translators: %d: number of included changes */
			_n(
				'%d included change',
				'%d included changes',
				includedChanges,
				'wcai-pa'
			),
			includedChanges
		);
	}, [ formData ] );

	const updateCachedData = ( edits: SuggestionFormData ) => {
		queryClient.setQueryData(
			suggestionQuery( { suggestionId } ).queryKey,
			( old ) => {
				if ( ! old ) {
					return old;
				}

				return {
					...old,
					changed_fields: old.changed_fields.map( ( field ) => {
						const edit = edits[ field.field ];

						if ( ! edit ) {
							return field;
						}

						return {
							...field,
							new_value: edit.new_value,
							included: edit.included,
						};
					} ),
				};
			}
		);
	};

	const handleSave = async () => {
		const changes = Object.entries( formData )
			.filter( ( [ , value ] ) => value.included )
			.map( ( [ field, value ] ) => ( {
				field,
				new_value: value.new_value,
			} ) );

		approveSuggestion.mutate( changes, {
			onSuccess: () => setIsExiting( true ),
		} );
	};

	const hasChangesToApply = useMemo( () => {
		return Object.values( formData ).some( ( field ) => field.included );
	}, [ formData ] );

	return (
		<div
			className={ `wcai-pa-suggestion-card__exit-wrapper${
				isExiting ? ' is-exiting' : ''
			}` }
			style={ {
				transition: `opacity ${ CARD_EXIT_DURATION_MS }ms ease-out`,
			} }
		>
			<Card size="medium">
				<button
					onClick={ () => setIsOpen( ! isOpen ) }
					className="wcai-pa-suggestion-card__toggle-button"
				>
					<CardHeader>
						<HStack justify="space-between">
							<HStack spacing={ 3 } style={ { width: 'auto' } }>
								<Text weight="bold">
									{ suggestion.product_name }
								</Text>
								{ suggestion.sku && suggestion.edit_url && (
									<a
										href={ suggestion.edit_url }
										target="_blank"
										rel="noreferrer"
										className="wcai-pa-suggestion-card__sku-link"
										onClick={ ( e ) => e.stopPropagation() }
									>
										{ suggestion.sku }
										<Icon icon={ external } size={ 16 } />
									</a>
								) }
							</HStack>
							<HStack spacing={ 4 } style={ { width: 'auto' } }>
								{ includedChangesMessage && (
									<Text color="muted">
										{ includedChangesMessage }
									</Text>
								) }
								{ isOpen ? (
									<Icon icon={ chevronUp } />
								) : (
									<Icon icon={ chevronDown } />
								) }
							</HStack>
						</HStack>
					</CardHeader>
				</button>
				{ isOpen && (
					<CardBody>
						<VStack
							spacing={ 8 }
							style={ { alignItems: 'flex-end' } }
						>
							<div className="wcai-pa-suggestion-card__form-container">
								<DataForm
									data={ formData }
									fields={ fields }
									form={ form }
									onChange={ updateCachedData }
								/>
							</div>
							<HStack spacing={ 8 } justify="space-between">
								<RejectSuggestion
									suggestionId={ suggestionId }
									onRejected={ () => setIsExiting( true ) }
								/>
								<HStack
									spacing={ 4 }
									justify="flex-end"
									style={ { width: 'auto' } }
								>
									{ approveSuggestion.error && (
										<Notice
											status="error"
											isDismissible={ false }
											className="wcai-pa-mutation-error-notice wcai-pa-mutation-error-notice--inline"
										>
											{ approveSuggestion.error.message }
										</Notice>
									) }
									<Button
										variant="primary"
										onClick={ handleSave }
										isBusy={ approveSuggestion.isPending }
										disabled={
											approveSuggestion.isPending ||
											! hasChangesToApply
										}
									>
										{ approveSuggestion.isPending
											? __(
													'Applying changes…',
													'wcai-pa'
											  )
											: __( 'Apply changes', 'wcai-pa' ) }
									</Button>
								</HStack>
							</HStack>
						</VStack>
					</CardBody>
				) }
			</Card>
		</div>
	);
}
